{
  "lesson_summary": "Today's lesson plans to teach students to recognise the place value of each digit in 2-digit numbers (tens, ones/units) and to count objects and numbers up to 99. It will focus on reading 2-digit numbers from tens-and-ones pictures, starting with an example of 6 tens circles and 1 loose counter to represent 61, and then counting on a number strip.",
  "lesson_summary_short": "Today's lesson plans to teach students to recognise place value in 2-digit numbers and count up to 99, using pictures of tens and ones.",
  "checks_summary": "This quiz checks whether the class can recognise place value in 2-digit numbers, read numbers from tens-and-ones pictures, and count forwards and backwards.",
  "questions": [
    {
      "slo_id": "S4",
      "level": "recall",
      "question": "In a number picture, what does one circle of 10 counters mean?",
      "options": [
        "One ten",
        "One one",
        "Ten tens"
      ],
      "correct_index": 0,
      "explanation": "One circle of 10 counters represents one group of ten, which is one ten.",
      "selected_because": "Key fact the lesson turns on: 'One circle of 10 counters means one ten'.",
      "distractor_misconceptions": {
        "1": "Confuses a group of ten with a single counter.",
        "2": "Misinterprets 'one circle of 10' as 'ten tens'."
      },
      "option_feedback": {
        "correct": "That's right! A circle of 10 counters shows one group of ten, or one ten.",
        "wrong": {
          "1": "Remember, a loose counter means one 'one'. A circle of 10 counters means one 'ten'.",
          "2": "A circle of 10 counters means one 'ten', not ten tens. Ten tens would be 100!"
        }
      },
      "figure": null,
      "figure_role": null
    },
    {
      "slo_id": "S3",
      "level": "understand",
      "question": "What number do these sticks show?",
      "options": [
        "34",
        "43",
        "7"
      ],
      "correct_index": 0,
      "explanation": "The picture shows 3 bundles of ten sticks and 4 loose sticks. This represents 3 tens and 4 ones, which is 34.",
      "selected_because": "Reading a 2-digit number from a base-ten picture.",
      "distractor_misconceptions": {
        "1": "Reverses the order of tens and ones.",
        "2": "Counts every stick as one, ignoring bundles of ten."
      },
      "option_feedback": {
        "correct": "Excellent! There are 3 bundles of ten and 4 loose sticks, so the number is 34.",
        "wrong": {
          "1": "Always read the tens first, then the ones. Count the bundles of ten first, then the loose sticks.",
          "2": "Be careful! Each bundle has 10 sticks. Count the tens first, then the ones. This picture shows 3 tens and 4 ones."
        }
      },
      "figure": {
        "type": "base_ten",
        "tens": 3,
        "ones": 4
      },
      "figure_role": "read_off"
    },
    {
      "slo_id": "S1",
      "level": "understand",
      "question": "In the number 61, what is the place value of the digit 6?",
      "options": [
        "Tens",
        "Ones",
        "Hundreds"
      ],
      "correct_index": 0,
      "explanation": "In a 2-digit number, the digit on the left represents the tens place, and the digit on the right represents the ones place. So, 6 is in the tens place.",
      "selected_because": "Recognising the place value of digits in 2-digit numbers, using the lesson's example 61.",
      "distractor_misconceptions": {
        "1": "Confuses the tens and ones places.",
        "2": "Incorrectly assigns a hundreds place to a 2-digit number."
      },
      "option_feedback": {
        "correct": "You got it! The digit 6 in 61 is in the tens place, meaning it represents 60.",
        "wrong": {
          "1": "The digit on the right is in the ones place. The digit on the left is in the tens place. In 61, the 1 is in the ones place.",
          "2": "61 is a 2-digit number, so it only has tens and ones places. There is no hundreds place."
        }
      },
      "figure": null,
      "figure_role": null
    },
    {
      "slo_id": "S5",
      "level": "understand",
      "question": "If you have 5 tens and 6 ones, how do you write the number?",
      "options": [
        "56",
        "65",
        "506"
      ],
      "correct_index": 0,
      "explanation": "To write a 2-digit number, you always write the tens digit first, then the ones digit. So, 5 tens and 6 ones is 56.",
      "selected_because": "Writing the tens digit first, then the ones digit, using the lesson's example.",
      "distractor_misconceptions": {
        "1": "Reverses the order of tens and ones.",
        "2": "Adds a zero between the tens and ones."
      },
      "option_feedback": {
        "correct": "That's correct! You write the tens digit first, then the ones digit, so 5 tens and 6 ones is 56.",
        "wrong": {
          "1": "Remember to write the tens digit first, then the ones digit. 5 tens and 6 ones makes 56.",
          "2": "When writing a 2-digit number, you put the tens digit and the ones digit next to each other. 5 tens and 6 ones is 56."
        }
      },
      "figure": null,
      "figure_role": null
    },
    {
      "slo_id": "S3",
      "level": "understand",
      "question": "What number is shown in this picture?",
      "options": [
        "24",
        "6",
        "42"
      ],
      "correct_index": 0,
      "explanation": "The picture shows 2 circles of 10 counters (2 tens) and 4 loose counters (4 ones). This makes the number 24.",
      "selected_because": "Addressing the misconception of counting every mark as one, using the lesson's example of 24.",
      "distractor_misconceptions": {
        "1": "Counts every mark as one, ignoring the value of the tens circles.",
        "2": "Reverses the order of tens and ones."
      },
      "option_feedback": {
        "correct": "Great job! The picture shows 2 tens and 4 ones, which is 24.",
        "wrong": {
          "1": "Be careful! Each circle has 10 counters. So you have 2 tens and 4 ones, which is 24, not 6.",
          "2": "Always read the tens first, then the ones. The picture shows 2 tens and 4 ones, which is 24."
        }
      },
      "figure": {
        "type": "count_objects",
        "rows": [
          {
            "picto": "counter",
            "count": 2,
            "group": 10,
            "label": "tens"
          },
          {
            "picto": "counter",
            "count": 4,
            "label": "ones"
          }
        ]
      },
      "figure_role": "read_off"
    },
    {
      "slo_id": "S2",
      "level": "understand",
      "question": "Hira steps forward twice from 68 on a number strip. What number does she land on?",
      "options": [
        "70",
        "66",
        "69"
      ],
      "correct_index": 0,
      "explanation": "Stepping forward twice from 68 means adding 2 to 68. So, 68 + 1 = 69, and 69 + 1 = 70.",
      "selected_because": "Counting forwards from a given number, using the lesson's example of Hira.",
      "distractor_misconceptions": {
        "1": "Counts backwards instead of forwards.",
        "2": "Counts forward only once instead of twice."
      },
      "option_feedback": {
        "correct": "You're right! Stepping forward twice from 68 means 68, then 69, then 70.",
        "wrong": {
          "1": "Hira steps forward, not backward. From 68, stepping forward means going to a bigger number.",
          "2": "Hira steps forward twice. So, from 68, it's 69, and then one more step to 70."
        }
      },
      "figure": null,
      "figure_role": null
    },
    {
      "slo_id": "S2",
      "level": "understand",
      "question": "Hamza steps back once from 70 on a number strip. What number does he land on?",
      "options": [
        "69",
        "71",
        "60"
      ],
      "correct_index": 0,
      "explanation": "Stepping back once from 70 means subtracting 1 from 70. So, 70 - 1 = 69.",
      "selected_because": "Counting backwards from a given number, using the lesson's example of Hamza.",
      "distractor_misconceptions": {
        "1": "Counts forwards instead of backwards.",
        "2": "Subtracts 10 instead of 1."
      },
      "option_feedback": {
        "correct": "Correct! Stepping back once from 70 means going to 69.",
        "wrong": {
          "1": "Hamza steps back, not forward. From 70, stepping back means going to a smaller number.",
          "2": "Hamza steps back once, which means subtracting 1. 70 minus 1 is 69."
        }
      },
      "figure": null,
      "figure_role": null
    },
    {
      "slo_id": "S1",
      "level": "understand",
      "question": "Which of these numbers has the digit 7 in the tens place?",
      "options": [
        "72",
        "27",
        "7"
      ],
      "correct_index": 0,
      "explanation": "The tens place is the digit on the left in a 2-digit number. In 72, the 7 is on the left, so it is in the tens place.",
      "selected_because": "Applying the concept of place value to a new number.",
      "distractor_misconceptions": {
        "1": "Confuses the tens and ones places.",
        "2": "Identifies the digit 7 in a single-digit number, which has no tens place."
      },
      "option_feedback": {
        "correct": "That's right! In 72, the 7 is in the tens place, meaning it represents 70.",
        "wrong": {
          "1": "In 27, the 7 is in the ones place. The tens place is the digit on the left.",
          "2": "The number 7 is a single-digit number, so it only has a ones place. It does not have a tens place."
        }
      },
      "figure": null,
      "figure_role": null
    }
  ]
}
